export const getTopicCurriculum = async (req, res, next) => {
  try {
    const { topicId } = req.params;
    const topic = await TopicModel.findOne({ id: topicId }).lean();
    if (!topic) {
      return res.status(404).json({ success: false, message: 'Topic not found' });
    }
    return res.status(200).json({ success: true, data: topic });
  } catch (err) {
    next(err); // Forward to centralized error middleware
  }
};

// client/hooks/useCurriculum.js
import { useState, useEffect } from 'react';

export function useCurriculum(topicId) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!topicId) return;
    let isMounted = true;
    setLoading(true);

    fetch(`/api/topics/${topicId}`)
      .then(res => res.json())
      .then(json => { if (isMounted) { setData(json.data); setLoading(false); } })
      .catch(err => { if (isMounted) { setError(err.message); setLoading(false); } });

    return () => { isMounted = false; };
  }, [topicId]);

  return { data, loading, error };
}

